import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Install Keel","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/install.md","filePath":"getting-started/install.md"}'),i={name:"getting-started/install.md"};function l(n,e,d,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="install-keel" tabindex="-1">Install Keel <a class="header-anchor" href="#install-keel" aria-label="Permalink to &quot;Install Keel&quot;">​</a></h1><p>Keel is not an npm or Wally package. You keep one checkout of the Keel repository, and <code>tools/keel.js</code> copies Keel&#39;s files into each game.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Why</th></tr></thead><tbody><tr><td><strong>Roblox Studio</strong> with <strong>Script Sync</strong></td><td>Studio syncs the <code>src/</code> folders to and from the files on disk.</td></tr><tr><td><strong>Node.js</strong></td><td><code>keel.js</code> is a plain Node script. It uses only Node&#39;s built-in modules, so there is nothing to <code>npm install</code> to use Keel. (This documentation site is the one exception: it needs Node 18 or newer, see its README.)</td></tr><tr><td><strong>Git</strong></td><td><code>keel.js</code> clones a tagged Keel version from GitHub when you install or update.</td></tr><tr><td><strong>Access to <code>Sorrbe/Keel</code></strong></td><td>The framework repository is private. These docs are public; the code is not.</td></tr></tbody></table><h2 id="get-keel" tabindex="-1">Get Keel <a class="header-anchor" href="#get-keel" aria-label="Permalink to &quot;Get Keel&quot;">​</a></h2><p>Clone the repository once, anywhere you keep projects:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Sorrbe/Keel.git</span></span></code></pre></div><p>That checkout is also Keel&#39;s own test place: it contains the framework, a small starter game and Keel&#39;s unit tests. You never edit Keel inside a game; you change it here, tag a version, and update your games. See <a href="/Keel-Docs/guides/releasing-keel">Releasing Keel</a>.</p><h2 id="check-that-it-works" tabindex="-1">Check that it works <a class="header-anchor" href="#check-that-it-works" aria-label="Permalink to &quot;Check that it works&quot;">​</a></h2><p>From the Keel checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/keel.js</span></span></code></pre></div><p>With no command it prints the usage line and exits with an error:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keel: usage: keel.js new &lt;dir&gt; [tag] | update &lt;tag|latest&gt; [--force] | status   (add --from &lt;path&gt; to use a local Keel checkout)</span></span></code></pre></div><p>That is the three commands Keel has. Next: <a href="/Keel-Docs/getting-started/create-a-game">create a game</a>.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>You do not need the Keel checkout inside a game. <code>new</code> copies <code>tools/keel.js</code> into the game, and from then on the game runs <code>node tools/keel.js update &lt;tag&gt;</code> itself, which clones the tag from GitHub into a temporary folder.</p></div>',15)])])}const u=t(i,[["render",l]]);export{g as __pageData,u as default};
